return item;

// Detect if text is Markdown, HTML, or plain text
function detectType(text) {
  const htmlPattern = /<\s*([a-z0-9]+)(\s+[^>]*)?>.*?<\s*\/\1>/is;
  const htmlSelfClosing = /<\s*([a-z0-9]+)(\s+[^>]*)?\/>/i;

  // Common Markdown patterns
  const markdownPatterns = [
    /^\s{0,3}#/m,                        // headings
    /\*\*.*\*\*/, /__.*__/,              // bold
    /\*[^*]+\*/, /_[^_]+_/,              // italic
    /\[[^\]]+\]\([^)]+\)/,               // links
    /^\s{0,3}- /m, /^\s{0,3}\* /m,       // lists
    /```[\s\S]*?```/,                    // code block
    /^\s{4,}/m,

    // indented code block
  ];

  // HTML detection
  if (htmlPattern.test(text) || htmlSelfClosing.test(text)) {
    return { type: 'html', confidence: 0.98 };
  }

  // Markdown detection
  let markdownMatches = 0;
  markdownPatterns.forEach((re) => { if (re.test(text)) markdownMatches++; });
  if (markdownMatches > 1) {
    return { type: 'markdown', confidence: 0.95 + 0.01 * markdownMatches };
  }

  // Fallback to plain text
  return { type: 'plain_text', confidence: 0.80 };
}

// n8n code node: passthrough all JSON fields
const text = $json.text || '';

return items.map(item => {
  const result = detectType(text);
  return {
    json: {
      ...item.json,
      detectedType: result.type,
      confidence: result.confidence,
      analysedText: text // Optional: include the analysed text for traceability
    }
  };
});

return items.map(item => {
  let htmlString = item.json.data || item.json.text || '';

  if (typeof htmlString === 'string' && htmlString.startsWith('"') && htmlString.endsWith('"')) {
    try {
      htmlString = JSON.parse(htmlString);
    } catch(e) {
      htmlString = htmlString
        .replace(/^"/, '').replace(/"$/, '')
        .replace(/\\"/g, '"')
        .replace(/\\n/g, '\n');
    }
  }

  htmlString = htmlString.trim();

  return {
    json: {
      ...item.json,
      data: htmlString
    }
  };
});

